escenas.Mundo:
// Mundo compartido: «¿Lavar el pollo crudo lo empeora todo?». Cocina en corte como maqueta: el fregadero a la izquierda y la estufa a la derecha.
// paso 0: fregadero con el grifo abierto, una mano sostiene la pechuga cruda, saltan gotitas verdes y hay bacterias en el pollo.
// paso 1: el pollo descansa en el fregadero; alrededor están la tabla verde con la ensalada, el cuchillo, el jabón y el papel.
// paso 2: aparece en la pared la tarjeta de los 4 mitos, todavía sin tachar.
// paso 3: hay manchas verdes en la encimera y la ensalada, y el mito 1 (agua) está tachado.
// paso 4: además, el cuchillo, las manos y la ensalada tienen manchas verdes brillantes.
// paso 5: jugo de limón en el fregadero, el limón está en la encimera y el mito 2 está tachado.
// paso 6: la botella de vinagre está en la encimera, el charco sigue en el fregadero y el mito 3 está tachado.
// paso 7: hay vapor y salpicaduras en el fregadero, y los 4 mitos están tachados.
// paso 8: la llama de la estufa está encendida bajo la sartén; el fregadero ya está limpio, el grifo cerrado y sin manchas.
// paso 9: el pollo seco está sobre la tabla roja y el papel usado está en la basura.
// paso 10: un cuchillo rojo y uno verde, cada uno en su tabla, con letreros que separan las zonas.
// paso 11: igual que el paso 10, con la cocina limpia.
// paso 12: el pollo dorado está en la sartén con el termómetro marcando 74 °C y ya no quedan bacterias.
import React from 'react';
import {Pieza, Ojos, Cartel, Linea} from '../lib3d';
import type {Paleta, V3} from '../lib3d';

export const PARTES = [
  'cocina', 'fregadero', 'grifo', 'chorro', 'vapor', 'gotas', 'pollo', 'bacterias', 'mano', 'manos',
  'manchas', 'contagio', 'cuchillo', 'tabla', 'ensalada', 'jabon', 'papel', 'basura', 'tarjeta',
  'limon', 'vinagre', 'charco', 'estufa', 'sarten', 'llama', 'tablaroja', 'cuchillorojo',
  'cuchilloverde', 'letrero', 'termometro', 'plato',
] as const;

export type ParteProps = {paleta: Paleta; resaltado?: boolean; frame?: number};
export type MundoProps = {paso: number; frame: number; fps: number; paleta: Paleta; ocultar?: string[]; resaltar?: string[]};

// Colores reales y apagados
const ACERO = '#A7ACAF';
const ACERO_OSC = '#7E8487';
const BLANCO = '#ECE8E0';
const MUEBLE = '#B98E62';
const PARED = '#DCD5C8';
const AZULEJO = '#CEC7B9';
const NEGRO = '#2E2E33';
const PIEL = '#E2B48E';
const MANGA = '#8A97A6';
const CRUDO = '#E7A4A0';
const DORADO = '#D29A4E';
const VERDE_BACT = '#7DBE45';
const VERDE_LUZ = '#9BE35A';
const ROJO = '#C8372D';
const HOJA = '#7FA35B';

const col = (p: Paleta, r: boolean | undefined, c: string) => (r ? p.acentos[2] : c);

// Dónde está cada cosa
export const FREGADERO: V3 = [-0.35, 0.34, -0.3];
export const SARTEN: V3 = [0.8, 0.635, -0.32];
export const TABLA_ROJA: V3 = [0.22, 0.565, -0.3];
export const TABLA_VERDE: V3 = [-0.85, 0.565, -0.42];
export const posPollo = (paso: number): V3 =>
  paso >= 12 ? [0.8, 0.7, -0.32] : paso >= 9 ? [0.22, 0.655, -0.3] : paso === 0 ? [-0.35, 0.5, -0.3] : [-0.35, 0.42, -0.3];
export const mitosTachados = (paso: number) => (paso >= 7 ? 4 : paso >= 6 ? 3 : paso >= 5 ? 2 : paso >= 3 ? 1 : 0);
export const tempTermometro = (paso: number) => (paso >= 12 ? 74 : 20);
export const anguloAguja = (temp: number) => 2.3 - (Math.min(100, Math.max(0, temp)) / 100) * 4.6;
export const grifoAbierto = (paso: number) => paso <= 7;

/** X roja de tachar (en un plano vertical). */
export const XRoja: React.FC<{posicion: V3; tam?: number; rotacion?: V3}> = ({posicion, tam = 0.08, rotacion = [0, 0, 0]}) => (
  <group position={posicion} rotation={rotacion}>
    {[1, -1].map((s) => (
      <Pieza key={s} forma="caja" medidas={[tam * 1.3, tam * 0.22, 0.01]} color={ROJO} rotacion={[0, 0, (Math.PI / 4) * s]} />
    ))}
  </group>
);

const Mancha: React.FC<{p: V3; r?: number}> = ({p, r = 0.03}) => (
  <Pieza forma="esfera" medidas={[r]} color={VERDE_LUZ} brillo="#4C8F20" posicion={p} escala={[1, 0.25, 1]} contorno={false} />
);

// ---------- Cocina (muebles, encimera en piezas alrededor del hueco del fregadero, paredes) ----------
export const Cocina: React.FC<ParteProps> = ({paleta, resaltado}) => {
  const top = col(paleta, resaltado, BLANCO);
  return (
    <group>
      {/* muebles bajos */}
      <Pieza forma="caja" medidas={[0.4, 0.5, 0.6]} color={MUEBLE} posicion={[-0.85, 0.25, -0.3]} />
      <Pieza forma="caja" medidas={[0.6, 0.33, 0.6]} color={MUEBLE} posicion={[-0.35, 0.165, -0.3]} />
      <Pieza forma="caja" medidas={[1.1, 0.5, 0.6]} color={MUEBLE} posicion={[0.5, 0.25, -0.3]} />
      <Pieza forma="caja" medidas={[0.3, 0.38, 0.01]} color="#A87E55" posicion={[-0.85, 0.24, 0.005]} />
      <Pieza forma="caja" medidas={[0.5, 0.26, 0.01]} color="#A87E55" posicion={[-0.35, 0.16, 0.005]} />
      <Pieza forma="caja" medidas={[0.04, 0.015, 0.02]} color={ACERO_OSC} posicion={[-0.85, 0.38, 0.015]} />
      {/* encimera */}
      <Pieza forma="caja" medidas={[0.4, 0.05, 0.66]} color={top} posicion={[-0.85, 0.525, -0.29]} />
      <Pieza forma="caja" medidas={[1.1, 0.05, 0.66]} color={top} posicion={[0.5, 0.525, -0.29]} />
      <Pieza forma="caja" medidas={[0.6, 0.05, 0.12]} color={top} posicion={[-0.35, 0.525, -0.56]} />
      {/* paredes en corte */}
      <Pieza forma="caja" medidas={[2.1, 1.0, 0.04]} color={PARED} posicion={[0, 1.05, -0.64]} />
      <Pieza forma="caja" medidas={[2.1, 0.28, 0.01]} color={AZULEJO} posicion={[0, 0.69, -0.615]} />
      <Pieza forma="caja" medidas={[0.04, 1.55, 0.7]} color={PARED} posicion={[-1.07, 0.775, -0.29]} />
      {/* portarrollos en la pared */}
      <Pieza forma="caja" medidas={[0.26, 0.02, 0.08]} color={ACERO_OSC} posicion={[-0.85, 1.03, -0.58]} />
    </group>
  );
};

export const Fregadero: React.FC<ParteProps> = ({paleta, resaltado}) => {
  const c = col(paleta, resaltado, ACERO);
  const [x, y, z] = FREGADERO;
  return (
    <group position={[x, y, z]}>
      <Pieza forma="caja" medidas={[0.6, 0.015, 0.4]} color={c} posicion={[0, 0.008, 0]} />
      <Pieza forma="caja" medidas={[0.6, 0.21, 0.015]} color={c} posicion={[0, 0.105, -0.2]} />
      <Pieza forma="caja" medidas={[0.015, 0.21, 0.4]} color={c} posicion={[-0.3, 0.105, 0]} />
      <Pieza forma="caja" medidas={[0.015, 0.21, 0.4]} color={c} posicion={[0.3, 0.105, 0]} />
      {/* borde delantero en corte (bajo, para ver dentro) */}
      <Pieza forma="caja" medidas={[0.6, 0.07, 0.015]} color={c} posicion={[0, 0.035, 0.2]} />
      <Pieza forma="cilindro" medidas={[0.035, 0.035, 0.006]} color={ACERO_OSC} posicion={[0, 0.018, 0]} />
      <Pieza forma="cilindro" medidas={[0.018, 0.018, 0.008]} color="#1E1E22" posicion={[0, 0.02, 0]} contorno={false} />
    </group>
  );
};

export const Grifo: React.FC<ParteProps> = ({paleta, resaltado}) => {
  const c = col(paleta, resaltado, ACERO);
  return (
    <group position={[-0.35, 0, 0]}>
      <Pieza forma="cilindro" medidas={[0.035, 0.042, 0.06]} color={c} posicion={[0, 0.58, -0.56]} />
      <Pieza forma="cilindro" medidas={[0.022, 0.022, 0.36]} color={c} posicion={[0, 0.76, -0.56]} />
      <Pieza forma="cilindro" medidas={[0.02, 0.02, 0.22]} color={c} posicion={[0, 0.93, -0.45]} rotacion={[Math.PI / 2, 0, 0]} />
      <Pieza forma="cilindro" medidas={[0.024, 0.018, 0.04]} color={c} posicion={[0, 0.915, -0.34]} />
      <Pieza forma="caja" medidas={[0.025, 0.02, 0.12]} color={c} posicion={[0, 0.96, -0.6]} rotacion={[0.3, 0, 0]} />
    </group>
  );
};

export const Chorro: React.FC<ParteProps> = ({paleta, resaltado, frame = 0}) => (
  <group position={[-0.35, 0, -0.34]}>
    <Pieza forma="cilindro" medidas={[0.016, 0.02, 0.42]} color={col(paleta, resaltado, '#BFD9EA')} posicion={[0, 0.685, 0]} opacidad={0.6} contorno={false} />
    <Pieza forma="toro" medidas={[0.03 + (frame % 8) * 0.004, 0.005]} color="#DCEBF4" posicion={[0, 0.49, 0.04]} rotacion={[Math.PI / 2, 0, 0]} contorno={false} />
  </group>
);

export const Vapor: React.FC<ParteProps> = ({frame = 0}) => (
  <group>
    {[0, 1, 2, 3, 4].map((i) => {
      const t = ((frame + i * 12) % 60) / 60;
      return (
        <Pieza key={i} forma="esfera" medidas={[0.05]} color="#F4F2EE" contorno={false} opacidad={0.5 * (1 - t)}
          posicion={[-0.35 + Math.sin(i * 2.1 + t * 3) * 0.12, 0.55 + t * 0.55, -0.3 + Math.cos(i * 1.7) * 0.08]} escala={0.6 + t * 1.2} />
      );
    })}
  </group>
);

/** Gotitas verdes que saltan del pollo en arcos (vida constante con frame). */
export const Gotas: React.FC<ParteProps & {paso?: number}> = ({paleta, resaltado, frame = 0, paso = 1}) => {
  const [ox, oy, oz] = posPollo(paso);
  return (
    <group>
      {[0, 1, 2, 3, 4, 5, 6].map((i) => {
        const t = ((frame + i * 7) % 24) / 24;
        const a = i * 0.9 + 0.3;
        return (
          <Pieza key={i} forma="esfera" medidas={[0.016]} color={col(paleta, resaltado, VERDE_LUZ)} brillo="#4C8F20" contorno={false}
            posicion={[ox + Math.cos(a) * 0.45 * t, oy + 0.08 + 0.45 * t - 0.55 * t * t, oz + Math.sin(a) * 0.25 * t + 0.05 * t]}
            escala={0.4 + Math.sin(Math.PI * t)} />
        );
      })}
    </group>
  );
};

// ---------- Protagonista ----------
export const Pollo: React.FC<ParteProps & {paso?: number}> = ({paleta, resaltado, frame = 0, paso = 1}) => {
  const cocido = paso >= 12;
  const c = col(paleta, resaltado, cocido ? DORADO : CRUDO);
  const respira = 1 + Math.sin(frame / 18) * 0.015;
  return (
    <group position={posPollo(paso)} rotation={[0, 0.25, 0]} scale={[1, respira, 1]}>
      <Pieza forma="esfera" medidas={[0.2]} color={c} escala={[1, 0.38, 0.65]} />
      <Pieza forma="esfera" medidas={[0.13]} color={c} posicion={[0.17, -0.005, 0.02]} escala={[1, 0.42, 0.75]} />
      {cocido
        ? [-0.08, 0, 0.08].map((x) => (
            <Pieza key={x} forma="caja" medidas={[0.015, 0.006, 0.18]} color="#7A4A22" posicion={[x, 0.074, 0]} rotacion={[0, 0.5, 0]} contorno={false} />
          ))
        : [-0.1, 0.02, 0.14].map((x, i) => (
            <Pieza key={x} forma="caja" medidas={[0.1, 0.004, 0.01]} color="#F6E3DC" posicion={[x, 0.074 - i * 0.004, -0.03 + i * 0.02]} rotacion={[0, 0.4, 0]} contorno={false} />
          ))}
      <Pieza forma="esfera" medidas={[0.03]} color="#FFFFFF" posicion={[-0.08, 0.068, -0.04]} escala={[1.4, 0.3, 0.7]} contorno={false} opacidad={0.7} />
      <Ojos posicion={[-0.04, 0.055, 0.1]} tam={0.035} separacion={0.085} rotacion={[-0.4, 0, 0]} frame={frame} />
      {[-1, 1].map((l) => (
        <Pieza key={l} forma="caja" medidas={[0.045, 0.008, 0.01]} color="#1B1B1F" posicion={[-0.04 + l * 0.043, 0.1, 0.095]} rotacion={[-0.4, 0, -0.25 * l]} contorno={false} />
      ))}
    </group>
  );
};

const Bacteria: React.FC<{p: V3; frame: number; i: number; color: string}> = ({p, frame, i, color}) => (
  <group position={[p[0], p[1] + Math.abs(Math.sin((frame + i * 11) / 9)) * 0.012, p[2]]} rotation={[0, Math.sin(frame / 25 + i) * 0.4, 0]}>
    <Pieza forma="esfera" medidas={[0.032]} color={color} escala={[1, 0.85, 1]} />
    <Ojos posicion={[0, 0.006, 0.025]} tam={0.011} separacion={0.026} frame={frame + i * 20} />
    <Pieza forma="caja" medidas={[0.014, 0.003, 0.004]} color="#1B1B1F" posicion={[0.004, -0.012, 0.031]} rotacion={[0, 0, 0.35]} contorno={false} />
  </group>
);

export const Bacterias: React.FC<ParteProps & {paso?: number}> = ({paleta, resaltado, frame = 0, paso = 1}) => {
  const [x, y, z] = posPollo(paso);
  const rel: V3[] = [[-0.1, 0.09, 0.03], [0.05, 0.1, -0.05], [0.15, 0.07, 0.06], [-0.01, 0.1, 0.07]];
  return (
    <group position={[x, y, z]}>
      {rel.map((r, i) => <Bacteria key={i} p={r} i={i} frame={frame} color={col(paleta, resaltado, VERDE_BACT)} />)}
    </group>
  );
};

// ---------- Manos ----------
const ManoForma: React.FC<{posicion: V3; rotacion?: V3; color: string; manchas?: boolean}> = ({posicion, rotacion = [0, 0, 0], color, manchas}) => (
  <group position={posicion} rotation={rotacion}>
    <Pieza forma="caja" medidas={[0.1, 0.03, 0.11]} color={color} />
    {[-0.036, -0.012, 0.012, 0.036].map((x) => (
      <Pieza key={x} forma="capsula" medidas={[0.012, 0.045]} color={color} posicion={[x, 0, -0.085]} rotacion={[Math.PI / 2, 0, 0]} />
    ))}
    <Pieza forma="capsula" medidas={[0.013, 0.035]} color={color} posicion={[0.065, 0, -0.01]} rotacion={[Math.PI / 2, 0, -0.9]} />
    <Pieza forma="cilindro" medidas={[0.045, 0.05, 0.16]} color={MANGA} posicion={[0, 0.005, 0.13]} rotacion={[Math.PI / 2, 0, 0]} />
    {manchas ? (
      <>
        <Mancha p={[-0.02, 0.016, -0.01]} r={0.022} />
        <Mancha p={[0.03, 0.016, 0.03]} r={0.016} />
      </>
    ) : null}
  </group>
);

/** Mano que sostiene la pechuga bajo el grifo (paso 0). */
export const Mano: React.FC<ParteProps> = ({paleta, resaltado}) => (
  <ManoForma posicion={[-0.33, 0.405, -0.27]} rotacion={[0.15, 0.2, 0]} color={col(paleta, resaltado, PIEL)} />
);

/** Par de manos contaminadas apoyadas en la encimera. */
export const Manos: React.FC<ParteProps> = ({paleta, resaltado}) => (
  <group>
    <ManoForma posicion={[0.06, 0.565, -0.14]} rotacion={[0, 0.25, 0]} color={col(paleta, resaltado, PIEL)} manchas />
    <ManoForma posicion={[0.36, 0.565, -0.14]} rotacion={[0, -0.25, 0]} color={col(paleta, resaltado, PIEL)} manchas />
  </group>
);

export const Manchas: React.FC<ParteProps> = () => (
  <group>
    {([[0.02, -0.32, 0.035], [0.14, -0.2, 0.025], [0.3, -0.42, 0.03], [-0.72, -0.22, 0.03], [-0.92, -0.58, 0.022], [-0.7, -0.05, 0.02], [-0.2, -0.57, 0.025]] as const).map(
      ([x, z, r], i) => <Mancha key={i} p={[x, 0.553, z]} r={r} />,
    )}
  </group>
);

/** Brillo verde en el cuchillo y la ensalada (contagio cruzado). */
export const Contagio: React.FC<ParteProps> = ({frame = 0}) => {
  const s = 1 + Math.sin(frame / 8) * 0.15;
  return (
    <group scale={1}>
      <Mancha p={[0.2, 0.575, -0.37]} r={0.02 * s} />
      <Mancha p={[0.08, 0.565, -0.44]} r={0.015 * s} />
      <Mancha p={[-0.82, 0.71, -0.06]} r={0.025 * s} />
      <Mancha p={[-0.9, 0.7, -0.12]} r={0.02 * s} />
    </group>
  );
};

// ---------- Utensilios ----------
const Cuchi: React.FC<{posicion: V3; rot?: number; mango: string}> = ({posicion, rot = 0, mango}) => (
  <group position={posicion} rotation={[0, rot, 0]}>
    <Pieza forma="caja" medidas={[0.2, 0.006, 0.04]} color="#C9CDD0" posicion={[-0.06, 0, 0]} />
    <Pieza forma="caja" medidas={[0.1, 0.022, 0.028]} color={mango} posicion={[0.09, 0.006, 0]} />
  </group>
);

export const Cuchillo: React.FC<ParteProps> = ({paleta, resaltado}) => (
  <Cuchi posicion={[0.14, 0.556, -0.42]} rot={0.4} mango={col(paleta, resaltado, '#4A4038')} />
);
export const CuchilloRojo: React.FC<ParteProps> = ({paleta, resaltado}) => (
  <Cuchi posicion={[0.24, 0.585, -0.2]} mango={col(paleta, resaltado, '#B3433A')} />
);
export const CuchilloVerde: React.FC<ParteProps> = ({paleta, resaltado}) => (
  <Cuchi posicion={[-0.85, 0.585, -0.3]} mango={col(paleta, resaltado, '#5E8C4E')} />
);

export const Tabla: React.FC<ParteProps> = ({paleta, resaltado}) => (
  <Pieza forma="caja" medidas={[0.34, 0.025, 0.3]} color={col(paleta, resaltado, '#7BA066')} posicion={TABLA_VERDE} />
);
export const TablaRoja: React.FC<ParteProps> = ({paleta, resaltado}) => (
  <Pieza forma="caja" medidas={[0.36, 0.025, 0.28]} color={col(paleta, resaltado, '#B9574A')} posicion={TABLA_ROJA} />
);

export const Ensalada: React.FC<ParteProps> = ({paleta, resaltado}) => (
  <group position={[-0.86, 0.55, -0.08]}>
    <Pieza forma="media_esfera" medidas={[0.12]} color={col(paleta, resaltado, paleta.acentos[1])} posicion={[0, 0.12, 0]} rotacion={[Math.PI, 0, 0]} />
    {[0, 1, 2, 3, 4].map((i) => (
      <Pieza key={i} forma="esfera" medidas={[0.045]} color={HOJA} posicion={[Math.cos(i * 1.26) * 0.06, 0.13, Math.sin(i * 1.26) * 0.06]} escala={[1, 0.6, 1]} />
    ))}
    <Pieza forma="esfera" medidas={[0.025]} color="#C2523F" posicion={[0.02, 0.165, 0.03]} />
    <Pieza forma="esfera" medidas={[0.022]} color="#C2523F" posicion={[-0.04, 0.16, -0.02]} />
  </group>
);

export const Jabon: React.FC<ParteProps> = ({paleta, resaltado}) => (
  <group position={[-0.1, 0.55, -0.55]}>
    <Pieza forma="cilindro" medidas={[0.035, 0.04, 0.13]} color={col(paleta, resaltado, '#8FB3C4')} posicion={[0, 0.065, 0]} />
    <Pieza forma="cilindro" medidas={[0.008, 0.008, 0.05]} color={BLANCO} posicion={[0, 0.155, 0]} />
    <Pieza forma="caja" medidas={[0.05, 0.01, 0.012]} color={BLANCO} posicion={[0, 0.18, 0.018]} />
  </group>
);

export const Papel: React.FC<ParteProps> = ({paleta, resaltado}) => (
  <group position={[-0.85, 0.96, -0.56]}>
    <Pieza forma="cilindro" medidas={[0.06, 0.06, 0.2]} color={col(paleta, resaltado, '#F3F0EA')} rotacion={[0, 0, Math.PI / 2]} />
    <Pieza forma="cilindro" medidas={[0.02, 0.02, 0.22]} color={ACERO_OSC} rotacion={[0, 0, Math.PI / 2]} />
    <Pieza forma="caja" medidas={[0.19, 0.12, 0.004]} color="#F3F0EA" posicion={[0, -0.07, 0.058]} />
  </group>
);

export const Basura: React.FC<ParteProps & {conPapel?: boolean}> = ({paleta, resaltado, conPapel}) => (
  <group position={[-0.85, 0, 0.35]}>
    <Pieza forma="cilindro" medidas={[0.13, 0.11, 0.32]} color={col(paleta, resaltado, '#8A9096')} posicion={[0, 0.16, 0]} />
    <Pieza forma="cilindro" medidas={[0.135, 0.135, 0.02]} color={ACERO_OSC} posicion={[0, 0.37, -0.11]} rotacion={[-1.1, 0, 0]} />
    <Pieza forma="caja" medidas={[0.07, 0.015, 0.05]} color={NEGRO} posicion={[0, 0.02, 0.13]} />
    {conPapel ? (
      <group position={[0, 0.33, 0]}>
        <Pieza forma="esfera" medidas={[0.055]} color="#F3F0EA" escala={[1, 0.8, 0.9]} />
        <Mancha p={[0.02, 0.03, 0.04]} r={0.015} />
      </group>
    ) : null}
  </group>
);

/** Tarjeta de los 4 mitos en la pared, con X rojas según cuántos van tachados. */
export const Tarjeta: React.FC<ParteProps & {tachados?: number}> = ({paleta, resaltado, tachados = 0}) => {
  const fijo: V3 = [0.0001, 0, 0];
