        </group>
        <group position={[0, 0, 0.018]} rotation={[0, 0, anguloAguja(temp)]}>
          <Pieza forma="caja" medidas={[0.005, 0.042, 0.003]} color="#1B1B1F" posicion={[0, 0.02, 0]} contorno={false} />
        </group>
        {temp >= 74 ? <Cartel texto="74 °C" posicion={[0, 0.12, 0]} alto={0.09} fondo={paleta.acentos[2]} colorTexto="#FFFFFF" /> : null}
      </group>
    </group>
  );
};

export const Letrero: React.FC<ParteProps> = ({paleta}) => (
  <group>
    <Linea desde={[0.38, 0.565, -0.42]} hasta={[0.38, 0.86, -0.42]} grosor={0.006} color="#5A4A3A" />
    <Cartel texto={'solo\npollo crudo'} posicion={[0.38, 0.92, -0.42]} alto={0.12} fondo={paleta.acentos[0]} colorTexto="#FFFFFF" />
    <Linea desde={[-0.72, 0.565, -0.55]} hasta={[-0.72, 0.86, -0.55]} grosor={0.006} color="#5A4A3A" />
    <Cartel texto="verduras" posicion={[-0.72, 0.9, -0.55]} alto={0.07} fondo="#6E9A5B" colorTexto="#FFFFFF" />
