/** Plato para servir (la escena final lo trae; queda sobre la encimera). */
export const Plato: React.FC<ParteProps> = ({paleta, resaltado}) => (
  <group position={[0.22, 0.55, -0.3]}>
    <Pieza forma="cilindro" medidas={[0.2, 0.15, 0.025]} color={col(paleta, resaltado, '#F5F2EC')} posicion={[0, 0.0125, 0]} />
    <Pieza forma="toro" medidas={[0.18, 0.008]} color="#E2DDD3" posicion={[0, 0.026, 0]} rotacion={[Math.PI / 2, 0, 0]} contorno={false} />
  </group>
);

// ---------- Mundo completo ----------
export const Mundo: React.FC<MundoProps> = ({paso, frame, paleta, ocultar = [], resaltar = []}) => {
  const ver = (n: string) => !ocultar.includes(n);
  const p = (n: string) => ({paleta, resaltado: resaltar.includes(n), frame});
  const sucio = paso >= 3 && paso <= 7;
  return (
    <group>
      {ver('cocina') && <Cocina {...p('cocina')} />}
      {ver('fregadero') && <Fregadero {...p('fregadero')} />}
      {ver('grifo') && <Grifo {...p('grifo')} />}
      {grifoAbierto(paso) && ver('chorro') && <Chorro {...p('chorro')} />}
      {grifoAbierto(paso) && ver('gotas') && <Gotas {...p('gotas')} paso={paso} />}
      {paso === 7 && ver('vapor') && <Vapor {...p('vapor')} />}
      {paso >= 5 && paso <= 7 && ver('charco') && <Charco {...p('charco')} paso={paso} />}

      {ver('pollo') && <Pollo {...p('pollo')} paso={paso} />}
      {paso <= 11 && ver('bacterias') && <Bacterias {...p('bacterias')} paso={paso} />}
      {paso === 0 && ver('mano') && <Mano {...p('mano')} />}
      {paso >= 4 && paso <= 7 && ver('manos') && <Manos {...p('manos')} />}
      {sucio && ver('manchas') && <Manchas {...p('manchas')} />}
      {paso >= 4 && paso <= 7 && ver('contagio') && <Contagio {...p('contagio')} />}

      {paso < 9 && ver('cuchillo') && <Cuchillo {...p('cuchillo')} />}
      {ver('tabla') && <Tabla {...p('tabla')} />}
      {ver('ensalada') && <Ensalada {...p('ensalada')} />}
      {ver('jabon') && <Jabon {...p('jabon')} />}
      {ver('papel') && <Papel {...p('papel')} />}
      {ver('basura') && <Basura {...p('basura')} conPapel={paso >= 9} />}
      {paso >= 2 && ver('tarjeta') && <Tarjeta {...p('tarjeta')} tachados={mitosTachados(paso)} />}
      {paso >= 5 && ver('limon') && <Limon {...p('limon')} />}
      {paso >= 6 && ver('vinagre') && <Vinagre {...p('vinagre')} />}

      {ver('estufa') && <Estufa {...p('estufa')} />}
      {ver('sarten') && <Sarten {...p('sarten')} />}
      {paso >= 8 && ver('llama') && <Llama {...p('llama')} />}
      {paso >= 9 && ver('tablaroja') && <TablaRoja {...p('tablaroja')} />}
      {paso >= 10 && ver('cuchillorojo') && <CuchilloRojo {...p('cuchillorojo')} />}
      {paso >= 10 && ver('cuchilloverde') && <CuchilloVerde {...p('cuchilloverde')} />}
      {paso >= 10 && ver('letrero') && <Letrero {...p('letrero')} />}
      {paso >= 12 && ver('termometro') && <Termometro {...p('termometro')} temp={tempTermometro(paso)} />}
    </group>
  );
};

